import sys

def summarize(values):
    count = total = 0
    for value in (n * 2 for n in values):
        count += 1
        total += value
    return count, total

def measure_sizes(values):
    whole_list = [n * 2 for n in values]
    generator = (n * 2 for n in values)
    return sys.getsizeof(whole_list), sys.getsizeof(generator)
